INSERT INTO `medconnectapp_testresult` VALUES (1,1,'2026-04-21 05:39:36.861799','2026-04-21 05:39:36.861826','BLOOD',NULL,'Bình thường',4,11),(2,1,'2026-04-23 08:08:41.922872','2026-04-23 08:08:41.922907','ULTRASOUND',NULL,'Thế vài nhưng đến cũng nếu mỗi như. Mỗi như điều một.',5,300),(3,1,'2026-04-23 08:08:41.978516','2026-04-23 08:08:41.978536','ULTRASOUND',NULL,'Không trong có số được cũng là. Điều cũng người sau cho.',9,331),(4,1,'2026-04-23 08:08:42.052451','2026-04-23 08:08:42.052479','OTHER',NULL,'Thay tự về nơi nếu. Cách mỗi cũng cái tại.',11,235),(5,1,'2026-04-23 08:08:42.064204','2026-04-23 08:08:42.064224','XRAY',NULL,'Trong điều có để hoặc đã lớn. Cách khi đó để một.',13,235),(6,1,'2026-04-23 08:08:42.091221','2026-04-23 08:08:42.091239','URINE',NULL,'Nào vậy vẫn hơn cũng. Từ thì như gần.',15,300),(7,1,'2026-04-23 08:08:42.111132','2026-04-23 08:08:42.111155','BLOOD',NULL,'Sẽ của đi từng cũng khiến vì. Bạn mỗi mà là về với từ.',16,300),(8,1,'2026-04-23 08:08:42.136054','2026-04-23 08:08:42.136079','XRAY',NULL,'Nếu rất nơi tại rất của tại thì. Của cho để. Bạn vài với cho hơn trong. Này thì làm như nào bạn.',17,274),(9,1,'2026-04-23 08:08:42.161506','2026-04-23 08:08:42.161527','OTHER',NULL,'Làm và cái. Sẽ là này đi lớn khiến người nhưng.',19,274),(10,1,'2026-04-23 08:08:42.179913','2026-04-23 08:08:42.179938','URINE',NULL,'Cũng mỗi cái. Vài thế được giữa cũng tại trong.\nTheo đã như nhưng. Đến một với hoặc.',20,160),(11,1,'2026-04-23 08:08:42.186183','2026-04-23 08:08:42.186201','XRAY',NULL,'Đang và thay. Các đó của. Đến đúng từ hơn.',21,160),(12,1,'2026-04-23 08:08:42.193017','2026-04-23 08:08:42.193037','XRAY',NULL,'Bạn mỗi giống mà giống được là. Với sẽ số tại cho nhưng rất.',22,160),(13,1,'2026-04-23 08:08:42.228158','2026-04-23 08:08:42.228182','BLOOD',NULL,'Chỉ để nào. Và hơn giữa được trong thì đi. Như được chỉ với đến thế.',23,342),(14,1,'2026-04-23 08:08:42.306438','2026-04-23 08:08:42.306461','BLOOD',NULL,'Đang bên được như vì hơn. Vẫn cách thay số. Từ của về cũng giống.\nĐi như nhiều của đến.',27,160),(15,1,'2026-04-23 08:08:42.335611','2026-04-23 08:08:42.335636','BLOOD',NULL,'Này chỉ để với.\nVài được đang bên cách nhưng. Của chỉ các các với.\nCũng tôi về nhưng. Các này của.',29,199),(16,1,'2026-04-23 08:08:42.416897','2026-04-23 08:08:42.416925','ULTRASOUND',NULL,'Không trong đó của. Đã tôi làm vì. Đến không đi từ bên một có cái. Đúng mà theo tôi.',32,265),(17,1,'2026-04-23 08:08:42.455036','2026-04-23 08:08:42.455060','OTHER',NULL,'Rất với sau giống. Lớn theo cũng đi nếu.\nTừ cũng từng tôi vẫn mỗi đi.',34,314),(18,1,'2026-04-23 08:08:42.462751','2026-04-23 08:08:42.462770','ULTRASOUND',NULL,'Một được như lớn đúng điều. Các trong thế với cũng. Tại cái khiến như.\nVẫn hơn như người như tại.',35,314),(19,1,'2026-04-23 08:08:42.505505','2026-04-23 08:08:42.505522','ULTRASOUND',NULL,'Để từ sẽ không. Điều từ cũng như nhiều.\nMỗi nào đến theo. Cho mỗi lớn để được. Tại đến từ nào.',36,244),(20,1,'2026-04-23 08:08:42.512231','2026-04-23 08:08:42.512251','OTHER',NULL,'Thế trong về hơn đúng. Có từ từ vẫn nào.',37,244),(21,1,'2026-04-23 08:08:42.529811','2026-04-23 08:08:42.529833','URINE',NULL,'Được đó từng có đang giữa. Không thay là cái có tôi của để. Đúng giống trong gần cách như.',38,254),(22,1,'2026-04-23 08:08:42.545259','2026-04-23 08:08:42.545280','XRAY',NULL,'Các là để cũng. Giống nếu bạn từng của.',40,254),(23,1,'2026-04-23 08:08:42.574335','2026-04-23 08:08:42.574359','XRAY',NULL,'Để hơn tự thế giống điều. Các đã giữa tôi là tại. Cái nào có như vì của.',41,174),(24,1,'2026-04-23 08:08:42.581422','2026-04-23 08:08:42.581443','URINE',NULL,'Có vẫn khi nào tại được. Cũng vậy sau từ vì tại.',42,174),(25,1,'2026-04-23 08:08:42.588153','2026-04-23 08:08:42.588173','ULTRASOUND',NULL,'Nào tôi như trong đúng khiến bên có. Có gần lớn giống chưa chưa giống.',43,174),(26,1,'2026-04-23 08:08:42.621036','2026-04-23 08:08:42.621056','URINE',NULL,'Đang này hoặc bạn bên đó. Từng nếu đến.',44,268),(27,1,'2026-04-23 08:08:42.628928','2026-04-23 08:08:42.628953','URINE',NULL,'Hơn để với. Có của của nào khi cách. Đó về lớn tôi vì cũng tôi.',45,268),(28,1,'2026-04-23 08:08:42.668696','2026-04-23 08:08:42.668725','URINE',NULL,'Giống tại thay theo nơi của. Vài mỗi sau trong tự. Khi rất chưa như.',47,267),(29,1,'2026-04-23 08:08:42.675297','2026-04-23 08:08:42.675317','BLOOD',NULL,'Số được với chỉ để hơn. Trong trong sẽ bên như. Các với chỉ đúng bạn cách.',48,267),(30,1,'2026-04-23 08:08:42.749458','2026-04-23 08:08:42.749480','ULTRASOUND',NULL,'Để với cho đang khiến từng. Theo tôi nào cũng với tôi.',51,274),(31,1,'2026-04-23 08:08:42.776694','2026-04-23 08:08:42.776727','URINE',NULL,'Như giống là vậy từ. Đã đúng và để hoặc.',53,254),(32,1,'2026-04-23 08:08:42.847486','2026-04-23 08:08:42.847516','XRAY',NULL,'Rất hoặc cách khi chỉ để vẫn. Và để nhưng giống. Trong nào đang tại theo cách.',57,268),(33,1,'2026-04-23 08:08:42.885208','2026-04-23 08:08:42.885230','URINE',NULL,'Đi trong đúng có các. Nhưng nhiều như trong đến thế. Nơi vậy trong thế như.',58,301),(34,1,'2026-04-23 08:08:42.896645','2026-04-23 08:08:42.896670','URINE',NULL,'Như thế vì giống. Bạn vẫn tự được như dưới.\nVới bên hơn vì để hơn. Đến chỉ dưới vẫn.',60,301),(35,1,'2026-04-23 08:08:42.926894','2026-04-23 08:08:42.926921','BLOOD',NULL,'Lớn để của hơn. Từ đến như các về của mỗi.\nBạn của cách vậy. Như số hơn thế.',62,235),(36,1,'2026-04-23 08:08:42.958017','2026-04-23 08:08:42.958045','URINE',NULL,'Của rất sau với hơn của. Bên vài và đến và để.',64,160),(37,1,'2026-04-23 08:08:42.991791','2026-04-23 08:08:42.991817','XRAY',NULL,'Nhưng này cũng đó về chỉ đúng. Trong rất với nơi. Giữa từ một theo.',67,152),(38,1,'2026-04-23 08:08:43.075034','2026-04-23 08:08:43.075061','XRAY',NULL,'Gần các được rất với như như. Của rất của từng của. Khiến để như.',72,274),(39,1,'2026-04-23 08:08:43.127077','2026-04-23 08:08:43.127094','BLOOD',NULL,'Cách đã của rất bên. Có lớn cái đi.\nCó tôi lớn nếu người điều bên chưa.\nTừ được hơn theo.',73,267),(40,1,'2026-04-23 08:08:43.166120','2026-04-23 08:08:43.166145','ULTRASOUND',NULL,'Đến khiến chưa như cái cái. Để theo làm đã. Như đang của nếu trong của lớn hơn.',75,278),(41,1,'2026-04-23 08:08:43.197143','2026-04-23 08:08:43.197171','OTHER',NULL,'Của vài được khiến sau. Số sau giữa sẽ. Chưa đang đến trong với.',77,160),(42,1,'2026-04-23 08:08:43.208627','2026-04-23 08:08:43.208651','OTHER',NULL,'Mà khiến vậy thay của để. Người có hơn như được cũng nhưng. Lớn thế vài với thay.',78,160),(43,1,'2026-04-23 08:08:43.245766','2026-04-23 08:08:43.245780','XRAY',NULL,'Dưới nào từng từ nhiều. Lớn thì đang đã. Giữa sẽ chỉ như vậy.\nGần cũng từ một bên của.',79,300),(44,1,'2026-04-23 08:08:43.253416','2026-04-23 08:08:43.253425','URINE',NULL,'Tự trong của. Chỉ được và của bên đó.',80,300),(45,1,'2026-04-23 08:08:43.273357','2026-04-23 08:08:43.273382','URINE',NULL,'Có vẫn tại. Và giữa về nhưng. Của vậy với như.',81,297),(46,1,'2026-04-23 08:08:43.329415','2026-04-23 08:08:43.329437','BLOOD',NULL,'Thì mà giữa. Vì có này này theo. Với và là hơn cũng này.',82,237),(47,1,'2026-04-23 08:08:43.343024','2026-04-23 08:08:43.343046','ULTRASOUND',NULL,'Nào nhiều dưới nhưng trong đó từng. Gần sau giữa đi gần là vài. Nếu với thay để để như bên.',84,237),(48,1,'2026-04-23 08:08:43.392913','2026-04-23 08:08:43.392936','ULTRASOUND',NULL,'Vậy này từng và sẽ. Bạn tôi giống của từng. Vài nào như bên trong bên.',85,238),(49,1,'2026-04-23 08:08:43.403006','2026-04-23 08:08:43.403028','XRAY',NULL,'Hơn theo tự trong này mỗi vẫn. Điều chỉ nào thay đúng.',87,238),(50,1,'2026-04-23 08:08:43.449418','2026-04-23 08:08:43.449437','OTHER',NULL,'Của tôi cách số với vài trong. Điều tôi số trong. Của vẫn đó đến cách.',90,237),(51,1,'2026-04-23 08:08:43.618209','2026-04-23 08:08:43.618229','URINE',NULL,'Chỉ có đang nếu một của nào. Người không theo chưa.',96,152),(52,1,'2026-04-23 08:08:43.719609','2026-04-23 08:08:43.719632','ULTRASOUND',NULL,'Đến đúng hơn khi từ để. Về từng có mà dưới tại.',99,244),(53,1,'2026-04-23 08:08:43.762384','2026-04-23 08:08:43.762413','URINE',NULL,'Cách làm từ nhiều.',101,267),(54,1,'2026-04-23 08:08:43.852173','2026-04-23 08:08:43.852196','BLOOD',NULL,'Đến giữa theo cũng để được. Cái giữa đã.\nLà của số nào nhưng. Số có đến. Về làm trong cái.',105,300),(55,1,'2026-04-23 08:08:43.951907','2026-04-23 08:08:43.951933','BLOOD',NULL,'Cho theo hơn có gần. Chỉ để các đúng với của thay. Gần nhiều trong để thì có khi.',108,238),(56,1,'2026-04-23 08:08:43.976511','2026-04-23 08:08:43.976536','OTHER',NULL,'Điều lớn tôi số như cũng. Bạn của làm hơn chỉ đã đã.',110,284),(57,1,'2026-04-23 08:08:43.982972','2026-04-23 08:08:43.982992','BLOOD',NULL,'Rất và tại đang. Của đó để cho như đã. Điều theo đi đó rất với rất.',111,284),(58,1,'2026-04-23 08:08:44.014129','2026-04-23 08:08:44.014147','ULTRASOUND',NULL,'Sẽ mà từng người. Người để nhưng trong bên tại.',112,300),(59,1,'2026-04-23 08:08:44.025108','2026-04-23 08:08:44.025127','URINE',NULL,'Tại của của. Cũng của gần trong người.\nTrong vài bạn hoặc. Để giữa nhiều của.',113,300),(60,1,'2026-04-23 08:08:44.034001','2026-04-23 08:08:44.034027','URINE',NULL,'Của như sau. Hơn làm đúng với. Tôi giữa cái này bạn số.',114,300),(61,1,'2026-04-23 08:08:44.055261','2026-04-23 08:08:44.055289','BLOOD',NULL,'Và có hoặc. Của để để gần thế. Của cho làm thì trong như.',115,152),(62,1,'2026-04-23 08:08:44.107308','2026-04-23 08:08:44.107331','XRAY',NULL,'Dưới có sau này cho vì từng như. Từ vẫn trong của. Thì chỉ vậy đang.',116,206),(63,1,'2026-04-23 08:08:44.116218','2026-04-23 08:08:44.116239','URINE',NULL,'Để số hoặc sẽ đã trong đi sau. Nhưng dưới của điều. Sau thay tôi của thì từ vậy gần.',117,206),(64,1,'2026-04-23 08:08:44.122775','2026-04-23 08:08:44.122798','URINE',NULL,'Cũng từ cũng nếu rất chỉ bạn hơn.\nCó tôi dưới để thay không. Tại như từ này để. Hoặc từ đi nơi.',118,206),(65,1,'2026-04-23 08:08:44.165522','2026-04-23 08:08:44.165541','OTHER',NULL,'Để đến cái cái tại của theo đi. Cũng tôi theo được. Thế gần của từ theo về. Giữa sẽ với thì.',120,278),(66,1,'2026-04-23 08:08:44.260041','2026-04-23 08:08:44.260063','OTHER',NULL,'Tự không giống.\nVới về như vài. Về gần cũng để để và khiến. Từng gần chỉ điều hơn.',123,278),(67,1,'2026-04-23 08:08:44.309138','2026-04-23 08:08:44.309168','XRAY',NULL,'Rất đang và để. Từng này cho thì.',125,278),(68,1,'2026-04-23 08:08:44.317913','2026-04-23 08:08:44.317935','BLOOD',NULL,'Vài có đang chỉ từ. Vài với làm vì để số.\nSau đi như cũng để và từ. Chưa trong bên theo khiến là.',126,278),(69,1,'2026-04-23 08:08:44.376289','2026-04-23 08:08:44.376309','OTHER',NULL,'Thì hơn vì từng để vậy. Trong dưới người để.\nTheo chỉ nào để. Như vài đúng vài mà.',128,206),(70,1,'2026-04-23 08:08:44.398206','2026-04-23 08:08:44.398226','ULTRASOUND',NULL,'Chưa về sau đã. Của bạn điều này vậy vì khi. Vẫn vài từng làm. Đã đó và mà giống các.',130,268),(71,1,'2026-04-23 08:08:44.422878','2026-04-23 08:08:44.422905','URINE',NULL,'Chưa hơn hoặc và. Cho từ như tự. Đi đang làm vì tại để bạn.',131,215),(72,1,'2026-04-23 08:08:44.429750','2026-04-23 08:08:44.429780','URINE',NULL,'Từ rất mỗi vì tại về. Mỗi giữa chỉ nếu để tự hoặc.\nTừ nào đúng vì sẽ. Của vậy và của.',132,215),(73,1,'2026-04-23 08:08:44.473350','2026-04-23 08:08:44.473386','XRAY',NULL,'Rất từng với một lớn thế giống. Làm bên hoặc cũng đúng.',133,314),(74,1,'2026-04-23 08:08:44.519851','2026-04-23 08:08:44.519863','ULTRASOUND',NULL,'Như trong đã gần bên. Cho khiến rất gần.',135,220),(75,1,'2026-04-23 08:08:44.569157','2026-04-23 08:08:44.569179','OTHER',NULL,'Sau như sau đang đúng như. Một các đã sẽ làm tại gần.',138,274),(76,1,'2026-04-23 08:08:44.658884','2026-04-23 08:08:44.658918','BLOOD',NULL,'Như sẽ đúng nào cái để mỗi. Hoặc nhiều tự chỉ trong khiến dưới.',141,206),(77,1,'2026-04-23 08:08:44.672577','2026-04-23 08:08:44.672634','ULTRASOUND',NULL,'Từ điều chưa cái.\nMỗi trong như đó cũng bạn. Tại tôi đó là như. Điều nếu vẫn nơi và từ gần.',143,206),(78,1,'2026-04-23 08:08:44.888983','2026-04-23 08:08:44.889017','BLOOD',NULL,'Của cái nào sẽ vài mà để. Đi vài về rất đi về.\nTrong sau số như như như. Mỗi về tại như cũng đi.',150,209),(79,1,'2026-04-23 08:08:44.941732','2026-04-23 08:08:44.941760','XRAY',NULL,'Tôi có với rất cũng. Một lớn cũng để để bên nhưng. Của từ từ thế dưới tại các.',151,152),(80,1,'2026-04-23 08:08:44.995258','2026-04-23 08:08:44.995288','OTHER',NULL,'Đúng nếu mà đang hơn. Mà giống nhiều.\nSau cách tôi hơn tại có. Giống cái như trong.',152,238),(81,1,'2026-04-23 08:08:45.003600','2026-04-23 08:08:45.003627','URINE',NULL,'Không dưới dưới từ như từ. Như trong như gần nơi vài. Thì nào dưới nếu của nào.',153,238),(82,1,'2026-04-23 08:08:45.011877','2026-04-23 08:08:45.011906','ULTRASOUND',NULL,'Cách làm nào tôi đã vài. Để có và như tại.\nĐể nhưng vài người nếu. Nếu một từng để.',154,238),(83,1,'2026-04-23 08:08:45.112317','2026-04-23 08:08:45.112352','URINE',NULL,'Đi tại vậy như.\nKhiến tại theo được. Nơi để của hoặc số làm. Giống khi vì đó rất từ vẫn.',159,244),(84,1,'2026-04-23 08:08:45.150383','2026-04-23 08:08:45.150417','ULTRASOUND',NULL,'Đang đi chưa mà lớn như một. Như nếu chỉ thế của để.\nTừ có với là. Gần gần sẽ số sau cũng thế.',160,206),(85,1,'2026-04-23 08:08:45.164115','2026-04-23 08:08:45.164142','XRAY',NULL,'Bên của đang sau như. Cái lớn nơi cho với làm chưa.',162,206),(86,1,'2026-04-23 08:08:45.231025','2026-04-23 08:08:45.231057','XRAY',NULL,'Giống vì mà vì trong mỗi thì vẫn. Của tôi trong rất đã các và. Với điều để vậy trong.',163,297),(87,1,'2026-04-23 08:08:45.256278','2026-04-23 08:08:45.256306','XRAY',NULL,'Lớn giữa đang rất. Tự giữa của nào.\nKhi với mà tại. Thì gần tự thì từ số.',165,278),(88,1,'2026-04-23 08:08:45.342120','2026-04-23 08:08:45.342146','URINE',NULL,'Của được của cũng. Trong tại các nhiều với về cho. Trong thì rất cho có thay nhưng.',168,301),(89,1,'2026-04-23 08:08:45.404355','2026-04-23 08:08:45.404403','ULTRASOUND',NULL,'Theo như thế số. Tại nào để tại có cái. Từng cách từ vài vẫn.',171,215),(90,1,'2026-04-23 08:08:45.454158','2026-04-23 08:08:45.454187','URINE',NULL,'Hơn vì gần của thế hoặc các. Hơn như hoặc đã của sẽ thế. Nơi có như nếu.',172,174),(91,1,'2026-04-23 08:08:45.491856','2026-04-23 08:08:45.491882','OTHER',NULL,'Gần cái từ giữa vài từng hơn. Để người thế đang của không.\nThay giống giữa cũng để như với.',173,331),(92,1,'2026-04-23 08:08:45.504774','2026-04-23 08:08:45.504825','ULTRASOUND',NULL,'Cái rất như của khi từ lớn. Có như đã nhiều đến với dưới đúng.',175,331),(93,1,'2026-04-23 08:08:45.541450','2026-04-23 08:08:45.541483','XRAY',NULL,'Hơn không nếu làm và có vài. Cũng đúng để khiến làm dưới. Về hơn tại của nếu bạn.',176,199),(94,1,'2026-04-23 08:08:45.581342','2026-04-23 08:08:45.581363','OTHER',NULL,'Đã tại lớn các người.\nVẫn một trong hơn trong tôi. Từ nào đó điều hoặc với với. Rất chưa khi dưới.',177,331),(95,1,'2026-04-23 08:08:45.595318','2026-04-23 08:08:45.595372','OTHER',NULL,'Khi tại với vài nếu giữa. Giống số vẫn của.',179,331),(96,1,'2026-04-23 08:08:45.636042','2026-04-23 08:08:45.636074','BLOOD',NULL,'Mỗi sau của. Và rất cũng người vẫn như.\nChỉ cho để cách được. Trong đang đó tại cho của cái từ.',181,245),(97,1,'2026-04-23 08:08:45.681666','2026-04-23 08:08:45.681716','XRAY',NULL,'Tôi có làm mỗi. Cho vẫn giữa đi như.\nTrong các nhiều nhưng theo tôi về. Vẫn giữa này.',183,284),(98,1,'2026-04-23 08:08:45.809252','2026-04-23 08:08:45.809283','OTHER',NULL,'Rất thế sau có. Làm vậy trong mỗi thì. Của của của có đã giữa để. Như giữa là không có.',187,297),(99,1,'2026-04-23 08:08:45.846304','2026-04-23 08:08:45.846335','OTHER',NULL,'Lớn hơn cũng điều như cũng từ. Giống là thế sẽ. Hơn thay cho đúng để thay không. Như của thay rất.',188,209),(100,1,'2026-04-23 08:08:45.856012','2026-04-23 08:08:45.856047','BLOOD',NULL,'Thay thay cái vài. Với hơn hơn của trong. Mà để được đi hơn.',189,209),(101,1,'2026-04-23 08:08:45.972351','2026-04-23 08:08:45.972385','OTHER',NULL,'Nơi mà là có. Khi vẫn có về đến nhiều.',194,301),(102,1,'2026-04-23 08:08:46.003915','2026-04-23 08:08:46.003948','OTHER',NULL,'Từng vài các hơn tôi từ thay. Với như giống.',195,199),(103,1,'2026-04-23 08:08:46.014738','2026-04-23 08:08:46.014766','BLOOD',NULL,'Của hơn vẫn nhưng. Rất bạn với không theo sau đi. Không tự lớn thì.',196,199),(104,1,'2026-04-23 08:08:46.069972','2026-04-23 08:08:46.070006','OTHER',NULL,'Không giống giống mỗi trong làm. Vậy điều theo vậy hơn.',197,235),(105,1,'2026-04-23 08:08:46.207130','2026-04-23 08:08:46.207184','BLOOD',NULL,'Làm cũng như không của có nhưng. Cái không và sẽ các chỉ chưa.\nNgười đang thì.',204,297),(106,1,'2026-04-23 08:08:46.275068','2026-04-23 08:08:46.275104','ULTRASOUND',NULL,'Bên bạn với như các và.\nTrong hoặc các. Chỉ hơn tôi và.',205,268),(107,1,'2026-04-23 08:08:46.290120','2026-04-23 08:08:46.290177','URINE',NULL,'Dưới từ đi bạn mà tôi. Người khiến như đó.',207,268),(108,1,'2026-04-23 08:08:46.351688','2026-04-23 08:08:46.351734','XRAY',NULL,'Nhiều thế thay giống nơi người vì. Tại là cái điều cũng đã nào tôi. Hơn bên của vì.',209,244),(109,1,'2026-04-23 08:08:46.387978','2026-04-23 08:08:46.388012','XRAY',NULL,'Như như lớn đang nơi cũng các. Từng đang theo. Khi làm nhiều là tôi từ khiến.',211,220),(110,1,'2026-04-23 08:08:46.417112','2026-04-23 08:08:46.417147','OTHER',NULL,'Thay có bên có cũng như. Hoặc sẽ làm có.\nRất đã tại để. Chưa trong hoặc đi với. Làm số một.',212,215),(111,1,'2026-04-23 08:08:46.629109','2026-04-23 08:08:46.629142','OTHER',NULL,'Cái thì giống vì hoặc để. Bên để cũng vẫn. Với hơn có đang đúng sẽ theo.',219,220),(112,1,'2026-04-23 08:08:46.669112','2026-04-23 08:08:46.669147','ULTRASOUND',NULL,'Theo trong có bạn của vậy giữa.',221,160),(113,1,'2026-04-23 08:08:46.718323','2026-04-23 08:08:46.718357','XRAY',NULL,'Đến cũng tự tự thì để. Với bạn có cái.',222,317),(114,1,'2026-04-23 08:08:46.731306','2026-04-23 08:08:46.731363','OTHER',NULL,'Đến giống đúng đã hơn thì. Giữa chưa thay không. Hơn chỉ vẫn vì tại để lớn.',223,317),(115,1,'2026-04-23 08:08:46.774298','2026-04-23 08:08:46.774354','XRAY',NULL,'Sẽ có tại có một đang thay hơn. Người không tự không thay vậy thì.',225,297),(116,1,'2026-04-23 08:08:46.784730','2026-04-23 08:08:46.784763','ULTRASOUND',NULL,'Về có chưa thì tại. Nơi tôi của lớn để sau đang nhiều.',226,297),(117,1,'2026-04-23 08:08:46.846162','2026-04-23 08:08:46.846203','ULTRASOUND',NULL,'Một đúng chưa có đúng số mỗi thay. Cũng tôi vì như đến thay tự.\nVề bên cách điều để thế.',228,206),(118,1,'2026-04-23 08:08:46.856486','2026-04-23 08:08:46.856536','BLOOD',NULL,'Từ đang người bên hơn. Có hơn nhiều khi từ cũng.',229,206),(119,1,'2026-04-23 08:08:46.866363','2026-04-23 08:08:46.866398','BLOOD',NULL,'Rất có làm vì chưa điều của. Đang vậy để từ làm.',230,206),(120,1,'2026-04-23 08:08:46.909583','2026-04-23 08:08:46.909621','ULTRASOUND',NULL,'Cũng số như không đó một của.\nLớn có này bên khiến của thay. Trong này không. Thế đã chưa hơn thay.',231,215),(121,1,'2026-04-23 08:08:46.919457','2026-04-23 08:08:46.919493','BLOOD',NULL,'Khiến cái điều gần với của là. Được nhưng lớn chỉ nhưng.',232,215),(122,1,'2026-04-23 08:08:46.982946','2026-04-23 08:08:46.982990','BLOOD',NULL,'Này từ tôi nhưng cái. Làm khiến mỗi tại để từng.',234,331),(123,1,'2026-04-23 08:08:47.019442','2026-04-23 08:08:47.019477','OTHER',NULL,'Bên nơi bạn như như. Chưa với để mà như vì rất.',235,238),(124,1,'2026-04-23 08:08:47.029008','2026-04-23 08:08:47.029044','ULTRASOUND',NULL,'Sẽ giống được chưa như. Với số không cách từ vậy. Từ dưới của làm đi như có.',236,238),(125,1,'2026-04-23 08:08:47.084781','2026-04-23 08:08:47.084844','URINE',NULL,'Bên giống theo vì này nhưng điều. Vì nhiều khi nơi tại. Tại đang trong hơn trong số.',239,235),(126,1,'2026-04-23 08:08:47.127016','2026-04-23 08:08:47.127071','URINE',NULL,'Như là từ để tại. Người điều này số cách từ để. Từ chỉ như đi với cũng.',241,331),(127,1,'2026-04-23 08:08:47.248260','2026-04-23 08:08:47.248316','XRAY',NULL,'Sẽ hơn để để đã đã. Tự giống như số một. Chỉ thay đến đi. Đúng tại tại bạn vẫn của.',245,244),(128,1,'2026-04-23 08:08:47.284694','2026-04-23 08:08:47.284831','XRAY',NULL,'Với không chưa giống cách. Để như một.\nSau thì với chưa thay bạn. Hơn cũng chỉ giống.',246,342),(129,1,'2026-04-23 08:08:47.318335','2026-04-23 08:08:47.318373','XRAY',NULL,'Vài có từ để. Như khiến điều nếu là.\nVậy tại dưới có. Đúng khi trong vì nhiều nào. Các đang đó vậy.',247,301),(130,1,'2026-04-23 08:08:47.327810','2026-04-23 08:08:47.327842','ULTRASOUND',NULL,'Như của hoặc chưa gần từng đúng. Của cách gần với được.',248,301),(131,1,'2026-04-23 08:08:47.444919','2026-04-23 08:08:47.444952','OTHER',NULL,'Đang số theo để không cái của. Như giống sẽ dưới dưới.',252,342),(132,1,'2026-04-23 08:08:47.455376','2026-04-23 08:08:47.455406','BLOOD',NULL,'Được có làm khi.\nTự điều các nhưng với. Giữa cho với vì. Nơi bên tôi người đó theo sau.',253,342),(133,1,'2026-04-23 08:08:47.502176','2026-04-23 08:08:47.502214','BLOOD',NULL,'Để cũng về khiến vài có. Điều nhiều tại như thì điều có.',255,301),(134,1,'2026-04-23 08:08:47.546005','2026-04-23 08:08:47.546038','URINE',NULL,'Này và lớn khi đã của thì. Chưa cái của với vài đang. Cũng để từ người để các.',258,300),(135,1,'2026-04-23 08:08:47.609848','2026-04-23 08:08:47.609903','XRAY',NULL,'Thế như tôi một. Như chỉ làm như hoặc vậy tự. Như rất hoặc. Gần từ nào tôi dưới điều đúng.',261,314),(136,1,'2026-04-23 08:08:47.652628','2026-04-23 08:08:47.652663','OTHER',NULL,'Chỉ hơn tôi hơn hơn đúng. Đã trong về để vậy trong từ trong. Về để điều số như để nào. Điều đến tự.',263,245),(137,1,'2026-04-23 08:08:47.744297','2026-04-23 08:08:47.744335','XRAY',NULL,'Để rất hơn hơn. Chưa sau để hơn với một.',265,297),(138,1,'2026-04-23 08:08:47.779904','2026-04-23 08:08:47.779968','BLOOD',NULL,'Điều bạn trong cho. Và đã từng người nào để. Hơn vài lớn như cách khi.\nKhi về như được.',266,301),(139,1,'2026-04-23 08:08:47.832684','2026-04-23 08:08:47.832753','ULTRASOUND',NULL,'Trong cũng có với điều. Đang một nơi. Đó làm thay.',268,317),(140,1,'2026-04-23 08:08:47.879592','2026-04-23 08:08:47.879646','OTHER',NULL,'Và tự sau. Của đúng của. Tại nhưng có nhiều đi là. Có để khiến vậy rất và như.',271,317),(141,1,'2026-04-23 08:08:47.890448','2026-04-23 08:08:47.890484','ULTRASOUND',NULL,'Bạn thì thay mà cũng bên điều. Cách số số mà khi.',272,317),(142,1,'2026-04-23 08:08:48.090150','2026-04-23 08:08:48.090186','BLOOD',NULL,'Cho như sẽ đúng tại nơi. Nếu từ thế đang mỗi. Của thì và như từng tại.',280,206),(143,1,'2026-04-23 08:08:48.207967','2026-04-23 08:08:48.208023','ULTRASOUND',NULL,'Của đúng sẽ như từ. Trong như giống bạn và. Đến tự từ đang.',283,301),(144,1,'2026-04-23 08:08:48.275527','2026-04-23 08:08:48.275550','XRAY',NULL,'Giống làm khiến thay cũng có của. Số bên một theo nào. Thay với làm như được thì thì.',287,199),(145,1,'2026-04-23 08:08:48.330020','2026-04-23 08:08:48.330072','OTHER',NULL,'Nơi trong vì người. Để như nào cũng thế giống.',288,215),(146,1,'2026-04-23 08:08:48.416172','2026-04-23 08:08:48.416210','OTHER',NULL,'Nhưng dưới nhiều tôi. Làm của hơn về. Thì để của đó thì giữa.',291,237),(147,1,'2026-04-23 08:08:48.458263','2026-04-23 08:08:48.458314','OTHER',NULL,'Hơn cách để khiến cũng dưới như. Nếu cách theo.\nNày của như để. Để để để đã khi đó một.',292,244),(148,1,'2026-04-23 08:08:48.467973','2026-04-23 08:08:48.468026','BLOOD',NULL,'Chưa là như tự nhưng vài trong. Từ để từng như hoặc. Của tôi theo của.',293,244),(149,1,'2026-04-23 08:08:48.494293','2026-04-23 08:08:48.494349','URINE',NULL,'Gần khi đến được không mà. Được hoặc lớn vì. Hơn nhưng hoặc số thì.',294,215),(150,1,'2026-04-23 08:08:48.503992','2026-04-23 08:08:48.504031','OTHER',NULL,'Như được của từ gần. Mà nơi cho và như là được.',295,215),(151,1,'2026-04-23 08:08:48.573505','2026-04-23 08:08:48.573539','URINE',NULL,'Để thì thay trong rất trong. Cho chỉ cũng.\nĐó một đến như bạn cái. Điều nơi điều vì.',297,267),(152,1,'2026-04-23 08:08:48.583479','2026-04-23 08:08:48.583513','BLOOD',NULL,'Tôi từ mỗi cũng để từ. Các được đó lớn.',298,267),(153,1,'2026-04-23 08:08:48.611551','2026-04-23 08:08:48.611588','OTHER',NULL,'Có có nơi nhưng không bên đang điều. Vì tại người thì gần nơi.',299,317),(154,1,'2026-04-23 08:08:48.687096','2026-04-23 08:08:48.687150','ULTRASOUND',NULL,'Để vì đó nhưng. Mỗi nhưng dưới đó các tại. Có này từ.\nBên nơi để.\nCũng cũng như rất để như một.',300,314),(155,1,'2026-04-23 08:08:48.768654','2026-04-23 08:08:48.768690','ULTRASOUND',NULL,'Đến của chỉ nhưng của tự. Thay nhiều người.\nCái thay đã. Tôi theo vài số sẽ mỗi các. Vì tôi tự.',303,220),(156,1,'2026-04-23 08:08:48.777498','2026-04-23 08:08:48.777531','XRAY',NULL,'Của mỗi nào bên. Như nhiều hơn là cũng. Vẫn như khi.',304,220),(157,1,'2026-04-23 08:08:48.868877','2026-04-23 08:08:48.868912','XRAY',NULL,'Là sẽ thay từng từ vẫn của. Của rất giữa cách cách thay của.',306,152),(158,1,'2026-04-23 08:08:48.892889','2026-04-23 08:08:48.892923','URINE',NULL,'Mà của cũng từng.',307,152),(159,1,'2026-04-23 08:08:48.928976','2026-04-23 08:08:48.929003','BLOOD',NULL,'Khiến để có. Cách vẫn chỉ người cách. Như về làm bên thay không từ.',308,152),(160,1,'2026-04-23 08:08:48.994688','2026-04-23 08:08:48.994719','XRAY',NULL,'Như tại để tự vài. Cũng vì tại về đến nơi có.',310,278),(161,1,'2026-04-23 08:08:49.048198','2026-04-23 08:08:49.048225','URINE',NULL,'Tại mà tự như cách từ đó đi. Của làm như như. Cũng tôi đã đã. Đúng nếu đó gần như.',314,206),(162,1,'2026-04-23 08:08:49.064892','2026-04-23 08:08:49.064902','OTHER',NULL,'Bạn đến đó mỗi điều làm vậy bạn. Cũng chỉ thế bạn tại đã. Một không trong vẫn là.',315,199),(163,1,'2026-04-23 08:08:49.118196','2026-04-23 08:08:49.118219','BLOOD',NULL,'Sẽ bên bạn thì đi hơn. Hơn chưa bên đã không và hơn. Chưa vậy điều sẽ cho.',318,152),(164,1,'2026-04-23 08:08:49.154317','2026-04-23 08:08:49.154341','BLOOD',NULL,'Từ từ giống của. Khi chỉ với lớn.',320,244),(165,1,'2026-04-23 08:08:49.189481','2026-04-23 08:08:49.189506','OTHER',NULL,'Số về để rất hơn được và từng. Trong về tại nào từng. Trong tự chỉ như số nếu.',321,278),(166,1,'2026-04-23 08:08:49.232608','2026-04-23 08:08:49.232641','XRAY',NULL,'Mà để nhưng mà. Tại như nhiều giữa cho. Nào thế giữa không.',322,244),(167,1,'2026-04-23 08:08:49.302437','2026-04-23 08:08:49.302456','ULTRASOUND',NULL,'Về cái được tại cũng vậy một bên. Có nếu sẽ tôi khiến.',326,331),(168,1,'2026-04-23 08:08:49.319505','2026-04-23 08:08:49.319520','URINE',NULL,'Về đang thế tôi. Làm lớn cũng nơi nhưng bạn của số.',327,215),(169,1,'2026-04-23 08:08:49.338589','2026-04-23 08:08:49.338610','URINE',NULL,'Vẫn sẽ lớn khi thì cách. Chưa này được bên dưới như. Mỗi đã các.',328,220),(170,1,'2026-04-23 08:08:49.345108','2026-04-23 08:08:49.345127','BLOOD',NULL,'Cái như chưa bạn hơn người. Và nhưng với nơi đó cũng.',329,220),(171,1,'2026-04-23 08:08:49.373594','2026-04-23 08:08:49.373608','ULTRASOUND',NULL,'Tôi có vậy điều khi vì. Khi đi này đang như.\nNhư sau các cũng. Nếu vài giống mà nơi từ.',331,342),(172,1,'2026-04-23 08:08:49.380477','2026-04-23 08:08:49.380497','OTHER',NULL,'Hơn này tôi đang nào của. Mỗi để thì giữa nào vài với.\nVì số tại giống như thay. Lớn đến các khi.',332,342),(173,1,'2026-04-23 08:08:49.435976','2026-04-23 08:08:49.436003','BLOOD',NULL,'Để người cũng đi tự. Đang và và vì của khi. Cách bên chưa có theo đi.',334,342),(174,1,'2026-04-23 08:08:49.446690','2026-04-23 08:08:49.446724','BLOOD',NULL,'Như tự trong với. Từng tự dưới vì tại đang.',336,342),(175,1,'2026-04-23 08:08:49.465731','2026-04-23 08:08:49.465759','URINE',NULL,'Tôi từ để tự từ từng vậy. Cũng vậy tôi một các đi đó. Nơi vậy nhiều nhiều làm chưa như.',337,244),(176,1,'2026-04-23 08:08:49.520804','2026-04-23 08:08:49.520825','XRAY',NULL,'Mà với đã có thay được có. Cho sau thế.',342,226),(177,1,'2026-04-23 08:08:49.527677','2026-04-23 08:08:49.527722','BLOOD',NULL,'Đến điều nơi sẽ nào tự để đúng. Thế này là để. Giữa tôi vài đã từng với.',343,226),(178,1,'2026-04-23 08:08:49.535256','2026-04-23 08:08:49.535281','XRAY',NULL,'Dưới đi cũng các với như. Để nơi đó bên của. Thế và đúng sau từng được là.',344,226),(179,1,'2026-04-23 08:08:49.554008','2026-04-23 08:08:49.554032','BLOOD',NULL,'Mỗi vậy nếu. Người hoặc để giữa bên thay. Thì để làm giống từng nào là.',345,297),(180,1,'2026-04-23 08:08:49.578545','2026-04-23 08:08:49.578565','OTHER',NULL,'Trong này như cho. Vài dưới nơi từ. Cách tôi của khi.\nTại một thế lớn lớn.',346,297),(181,1,'2026-04-23 08:08:49.585280','2026-04-23 08:08:49.585306','URINE',NULL,'Của thế là một đến mỗi nếu dưới. Cho rất hơn là nào thì một.',347,297),(182,1,'2026-04-23 08:08:49.640856','2026-04-23 08:08:49.640878','XRAY',NULL,'Bên như đúng lớn. Đang lớn vài theo theo từng cũng mỗi.',350,317),(183,1,'2026-04-23 08:08:49.647860','2026-04-23 08:08:49.647878','XRAY',NULL,'Để của gần có vì khi đúng. Giữa tại như làm nào sau cách vài. Các được vậy khi tôi trong.',351,317),(184,1,'2026-04-23 08:08:49.703715','2026-04-23 08:08:49.703743','ULTRASOUND',NULL,'Như nhiều mà với hơn cũng. Dưới đúng từng khi hơn.',355,274),(185,1,'2026-04-23 08:08:49.712396','2026-04-23 08:08:49.712425','ULTRASOUND',NULL,'Lớn được đúng. Giữa sau của là.',356,274),(186,1,'2026-04-23 08:08:49.758917','2026-04-23 08:08:49.758941','URINE',NULL,'Để như thế này mà. Đang thì nếu người cũng khiến. Một chỉ hơn bên có đó người nếu.',357,222),(187,1,'2026-04-23 08:08:49.766002','2026-04-23 08:08:49.766025','URINE',NULL,'Mà thế cách giữa bạn. Giữa cho hơn có.\nCó hơn đã có như. Để rất của thì cách thì.',358,222),(188,1,'2026-04-23 08:08:49.773235','2026-04-23 08:08:49.773269','URINE',NULL,'Rất là của nơi này cũng. Mà để đến cách.',359,222),(189,1,'2026-04-23 08:08:49.828886','2026-04-23 08:08:49.828910','XRAY',NULL,'Trong người cũng như cũng cho tự. Để một có mỗi cách hơn vẫn. Từ từ là này chỉ thay chưa.',361,284),(190,1,'2026-04-23 08:08:49.843962','2026-04-23 08:08:49.843986','XRAY',NULL,'Dưới dưới từ làm lớn làm. Rất nào giữa đến khiến.\nHơn giống làm thay vài. Nhiều chỉ cái có.',363,284),(191,1,'2026-04-23 08:08:49.908490','2026-04-23 08:08:49.908509','BLOOD',NULL,'Thay mà của. Với của cái từng đó tự. Khiến hơn giống với dưới cũng như một.',365,284),(192,1,'2026-04-23 08:08:49.941960','2026-04-23 08:08:49.941977','ULTRASOUND',NULL,'Để cho nhiều đang cái cũng là. Như đó đang tại giữa với này.',367,284),(193,1,'2026-04-23 08:08:49.948742','2026-04-23 08:08:49.948765','URINE',NULL,'Của hơn có tại không. Khi này mà nhiều.\nThế đi này có được thay. Từng dưới làm của như này cũng.',368,284),(194,1,'2026-04-23 08:08:50.045855','2026-04-23 08:08:50.045882','OTHER',NULL,'Cũng hoặc hơn được bạn không của có.',373,206),(195,1,'2026-04-23 08:08:50.083596','2026-04-23 08:08:50.083615','BLOOD',NULL,'Người sẽ để vài đó. Trong của đó điều đó một với. Tự giống có các.',375,314),(196,1,'2026-04-23 08:08:50.146501','2026-04-23 08:08:50.146521','ULTRASOUND',NULL,'Cách thì điều và giữa. Nhưng này lớn tôi. Cách giữa để mà.',379,278),(197,1,'2026-04-23 08:08:50.169908','2026-04-23 08:08:50.169938','OTHER',NULL,'Thì cho vì vài các của có.\nTheo có vậy đến không tự nào. Đã đến đó mà.\nTôi điều cho vậy.',381,160),(198,1,'2026-04-23 08:08:50.235564','2026-04-23 08:08:50.235591','BLOOD',NULL,'Giữa vậy nhưng đã nơi. Có một giống người tôi này từ. Cái cách trong của.',383,274),(199,1,'2026-04-23 08:08:50.386423','2026-04-23 08:08:50.386444','OTHER',NULL,'Nơi như đi sẽ của mà cách. Nhưng đến của giống nơi.\nTự tại vậy. Và hoặc đúng mà cũng cũng như.',389,226),(200,1,'2026-04-23 08:08:50.393932','2026-04-23 08:08:50.393958','ULTRASOUND',NULL,'Các từ để trong. Là để về thay mỗi tại. Lớn một đó người. Chỉ mỗi tại và gần.',390,226),(201,1,'2026-05-01 14:56:33.813538','2026-05-01 14:56:33.813563','BLOOD',NULL,'Bình thường',391,10),(203,1,'2026-05-01 15:00:41.178707','2026-05-01 15:00:41.178750','XRAY',NULL,'Bất thường',392,10),(206,1,'2026-05-02 16:42:02.911990','2026-05-02 16:42:02.912016','XRAY',NULL,'Bình thường',394,10),(208,1,'2026-05-16 12:24:36.174994','2026-05-16 12:24:36.175029','ULTRASOUND','{\"field 1\": \"abc\", \"field 2\": \"def\"}','Bình thường',393,10);
